// Convenience access over the generated partner-template data.
//
// The data and its classes live in im_partner_templates.g.dart (generated by
// app/tool/partner_templates.py from tooling/partner_templates/). This file only
// adds lookups; it holds no copy text, so the l10n scan has nothing to find.

import 'im_partner_templates.g.dart';

export 'im_partner_templates.g.dart';

/// Templates whose prompt is reviewed and that can be created today.
Iterable<PartnerTemplate> get availablePartnerTemplates => partnerTemplates.where((template) => template.available);

/// The six the companion tab shows first, in the order the generator emitted.
Iterable<PartnerTemplate> get featuredPartnerTemplates => partnerTemplates.where((template) => template.featured);

/// A template by its list key (`grok.pr-reviewer`), or null.
PartnerTemplate? partnerTemplateOf(String id) {
  for (final template in partnerTemplates) {
    if (template.id == id) return template;
  }
  return null;
}

/// The category row for a template, or the first category when the id is unknown.
PartnerTemplateCategory categoryOf(PartnerTemplate template) {
  for (final category in partnerTemplateCategories) {
    if (category.id == template.category) return category;
  }
  return partnerTemplateCategories.first;
}
